"""Record CPU boundary control/data logic, linkage and reasoning limits."""
from datetime import datetime,timezone
import json,subprocess,hashlib,urllib.request
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text())
def save(p,v):p.write_text(json.dumps(v,indent=2)+'\n')

def main():
    now=datetime.now(timezone.utc).isoformat();checks=read(ROOT/'verification/biwn-boundary-handlers-checks.json');linked=read(ROOT/'verification/biwn-world-boundary-pipeline-checks.json');reasoning=read(ROOT/'verification/boundary-reasoning-audit.json')
    assert checks['CPU_cases']==1450 and checks['covered_CPU_instructions']==135 and checks['host_guards']==23
    assert linked['cases']==256 and linked['type1_handler_calls']==49 and linked['type2_handler_calls']==62 and linked['redraw_cases']==166
    for name,digest in checks['source_sha256'].items():assert hashlib.sha256((ROOT/'projects/black-ice-white-noise/restoration'/name).read_bytes()).hexdigest()==digest
    assert [x['semantic_correct_fields']for x in reasoning['runs']]==[3,None,6]
    path=ROOT/'verification/easy-boundary/20261013T080015.663935Z/protocol.json';ease=read(path);assert ease['status']=='completed_pending_coordinator_review'
    rows=[]
    for i,q in enumerate(ease['questions']):
        calls=[b['toolCallRequest']for e in q['events']if e['role']=='assistant'for b in e['content']if b['type']=='toolCallRequest']
        answer='\n'.join(b['text']for e in q['events']if e['role']=='assistant'for b in e['content']if b['type']=='text').strip()
        assert len(calls)==1 and calls[0]['name']=='project_evidence' and calls[0]['arguments']=={'topic':'boundary_handlers'} and len(answer.split())<=[40,40,60][i]
        rows.append({'question':q['user'],'answer':answer,'seconds':q['SDK_reported_seconds'],'tool_calls':calls,'verdict':'matches checked current evidence and limits'})
    assert '0xabcd0000'in rows[0]['answer'] and '95'in rows[1]['answer'] and 'Ten nested'in rows[2]['answer'] and 'five other'in rows[2]['answer']
    review={'recorded_at':now,'status':'three_plain_boundary_questions_passed','directory':str(path.parent),'questions':rows,'scope':'Local SDK tool choice/factual responses using workbench evidence; installed MCP separately checked. Native Chat visual adoption unverified while locked.'}
    save(path.parent/'coordinator-review.json',review);save(ROOT/'verification/easy-boundary-review.json',review)
    with urllib.request.urlopen('http://127.0.0.1:1234/api/v1/models')as response:catalog=json.load(response)
    base=next(x for x in catalog['models']if x['key']=='local/advertising-qwen38');assert base['capabilities']['reasoning']['default']=='off'
    reasoning['live_reasoning_default_after_trials']='off';save(ROOT/'verification/boundary-reasoning-audit.json',reasoning)
    models=json.loads(subprocess.check_output([str(Path.home()/'.lmstudio/bin/lms'),'ps','--json'],cwd=Path.home()/'.lmstudio',text=True));assert len(models)==1 and models[0]['identifier']=='advertising-scholar' and models[0]['status']=='idle' and models[0]['contextLength']==32768
    session=Path(read(ROOT/'projects/black-ice-white-noise/analysis/current-session.json')['directory']);validation=read(session/'boot-slice-validation.json');assert validation['portable_C_component_count']==26;validation['latest_aggregate_update']=now;save(session/'boot-slice-validation.json',validation)
    game=('26 checked C components: 24 CPU and two GPU. Two CPU boundary handlers now match 1,450 original-execution cases (970 type 1, 480 type 2), with all 135 decoded instructions covered and 23 host guards. '
          'Checks preserve full D0, signed word/index arithmetic, index/target rereads, table scan behavior and subtraction from the post-helper neighbor value. '
          'The connected update/movement/boundary/inventory path matches 256 original CPU/GPU cases, including 49 type-1 calls, 62 type-2 calls and 166 inventory redraws. '
          'The rebuilt path executes no original CPU/GPU instructions and no complete game frames. Five other top-level targets and ten nested geometry/transition targets remain scripted on this path. '
          'Boundary control/data logic is reconstructed; lower collision geometry, transitions, full scene/main loop, audio, complete game and hardware validation remain unfinished. Pinned blitter and synchronous GPU dispatcher models remain dependencies.')
    frontend=('Game Assistant has current boundary_handlers/world_update/movement_matrix evidence. Three normal boundary questions used one evidence call each and answered correctly in 8.3–8.8 seconds. '
              'Everyday model stays thinking off, 32,768 context, one worker. Native Chat adoption/display remains unverified while locked; API exchanges are saved outside native history. Inventory PNG/action tool remains installed.')
    quality=('One fresh source-reading response per setting: reasoning off answered 3 of 7 fields correctly in 7.52 seconds. Low reasoning with 1,536 output tokens exhausted its allowance after 66.98 seconds with no final answer; accuracy unevaluated. '
             'One low retry with 4,096 tokens produced a final answer in 143.79 seconds: 6 of 7 fields correct after removing Markdown fences, but the cross-64 KB D0 result remained wrong and JSON-only formatting failed. '
             'These are narrow same-weight samples, not independent verification or a general ranking. No model code accepted, weights trained or defaults promoted this turn.')
    pending=('Implement the lower geometry/transition services and remaining update-path helpers; broaden scene/main-loop integration and investigate audio. Continue local-model quality evaluation and native Chat verification when accessible. '
             'Advertising Source Pilot v1 remains trained, loadable and experimental; everyday base remains default. Future 256 GB hardware is unbenchmarked. Full goal active and incomplete.')
    evidence=['verification/biwn-boundary-handlers-checks.json','verification/biwn-world-boundary-pipeline-checks.json','verification/boundary-checked-examples.json','verification/boundary-reasoning-audit.json','verification/boundary-MCP-check.json','verification/easy-boundary-review.json']
    for name in ['setup-status.json','current-runtime-state.json','everyday-inference.json','requirements-audit.json']:
        p=ROOT/'verification'/name;d=read(p)
        if name=='setup-status.json':d.update(updated_at_utc=now,game_work=game,frontend=frontend,pending=pending,latest_boundary_reasoning_quality=quality)
        elif name=='current-runtime-state.json':d.update(recorded_at=now,models=models,model_state_refreshed_at=now,decomp_progress=game,visible_chat=frontend,MCP_updated_evidence=frontend,
            local_inference_jobs='Three source-reading trials (off, capped low, larger low retry) and three evidence-assisted requests terminal. Usual 27B idle; default reasoning verified off. No background training/inference claimed.',
            emulator_jobs='1,450 boundary cases/23 guards, two fresh exact examples, 256 connected cases and original pre-boundary key derivations terminal. Pinned core and native movement/render libraries unchanged.',latest_API_ease_review=str(ROOT/evidence[-1]))
        elif name=='everyday-inference.json':d.update(updated_at=now,model=models,model_state_refreshed_at=now,frontend=frontend,latest_API_ease_review=str(ROOT/evidence[-1]),latest_boundary_reasoning_review=str(ROOT/evidence[3]))
        else:
            d.update(recorded_at_utc=now,previous_goal_turn_classification=d['this_goal_turn_classification'],this_goal_turn_classification='progress: two CPU boundary handlers match1450cases/135instructions;linked256cases;reasoning-budget/source-reading limits measured;three ordinary evidence-assisted questions pass',next_safe_work=pending)
            for item in d['requirements']:
                if 'decompilation test'in item['requirement']:item['state']=game;item['evidence']=list(dict.fromkeys(item['evidence']+evidence))
                elif 'Configure LM frontend'in item['requirement']:item['state']=frontend;item['evidence']=list(dict.fromkeys(item['evidence']+evidence[-2:]))
                elif 'Multiagent game'in item['requirement']:item['state']+=' Two fresh same-weight source-reading modes plus one budget retry were audited. Deliberation improved this narrow field score but retained a factual error; defaults unchanged.';item['evidence']=list(dict.fromkeys(item['evidence']+[evidence[3]]))
            d['post_review_evidence'].update({Path(e).name:str(ROOT/e)for e in evidence})
        save(p,d)
    config=read(ROOT/'config.json');config['chat_frontend']['game']['status']=game+' '+frontend;save(ROOT/'config.json',config)
    intake=read(ROOT/'corpus/game/project-intake.json');intake.update(latest_checked_at=now,latest_checked_status=game,latest_boundary_pipeline_check=str(ROOT/evidence[1]));save(ROOT/'corpus/game/project-intake.json',intake)
    (ROOT/'CURRENT DECOMPILATION.txt').write_text('BLACK ICE WHITE NOISE — CURRENT RECONSTRUCTION\n\n'+game+'\n\nBOUNDARY SOURCE\n'+str(ROOT/'projects/black-ice-white-noise/restoration/biwn_boundary_handlers.c')+'\n'+str(ROOT/'projects/black-ice-white-noise/restoration/biwn_boundary_handlers.h')+'\n\nLINKED CHECKS\n'+str(ROOT/evidence[1])+'\n\nEXACT RETURN/ROLLBACK EXAMPLES\n'+str(ROOT/evidence[2])+'\n\nMODEL QUALITY\n'+quality+'\n\nEASY CHAT\n'+frontend+'\n\nApproximate CPU export: 18,306 decoded instructions and 206 entry candidates. Analyst function/position labels are not original symbols. Integration does not add original components.\n\n'+pending+'\n')
    (ROOT/'START HERE.txt').write_text('LOCAL AI — DAILY USE\n\n1. Open LM Studio.\n2. Select Game Assistant — Quick Start or Advertising Assistant — Research & Teaching.\n3. Load the last used model if needed and type normally. Expand tool calls to inspect evidence.\n\nEveryday model: Advertising Qwen38; thinking off, 32,768 context, one worker.\n\nTRY IN GAME ASSISTANT\nShow the rebuilt inventory starting at position 1 with $200.\nStart at position 9, advance twice and show the resulting inventory panel.\nAre we done with collision now that both CPU boundary handlers are ported?\nThe neighbor starts 10, delta 5, and geometry changes it to 100 before failing. What is it after the handler undoes the delta?\n\nCURRENT GAME RESULT\n'+game+'\n\nCHAT RESULTS\n'+frontend+'\n\nTRY IN ADVERTISING ASSISTANT\nUsing Lee & Koo (2016), was involvement measured or manipulated?\nMake a lesson on the involvement scale with an objective, hypothetical example, student question and independently scored answer key.\n\nAdvertising Source Pilot v1 is trained, loadable and experimental. Everyday base remains default; source and teaching review still matter. See TRY ADVERTISING PILOT.txt.\n\nSOURCE REVIEW\n'+quality+'\n\nAUDIT\nPOST REVIEW.txt links exact prompts, final responses, tools, errors and coordinator corrections. Local API work does not automatically appear in native Chat history.\n\nThe verified CDI is internal; current checks do not require the external game drive. Eject it before unplugging.\n')
    p=ROOT/'projects/black-ice-white-noise/restoration/READ ME.txt';p.write_text(p.read_text()+'\nCPU BOUNDARY HANDLERS — '+now+'\n'+game+'\nReproduce: .venv/bin/python scripts/check_biwn_boundary_handlers.py and scripts/check_biwn_world_boundary_pipeline.py. Two separate original CPU functions; nested services explicitly scripted. Full D0 verified standalone; connected caller uses only its low word.\n')
    p=ROOT/'POST REVIEW.txt';p.write_text(p.read_text()+'\nCPU BOUNDARY HANDLERS / REASONING SETTINGS — '+now+'\n'+game+'\nWHO DID WHAT: Codex translated complete CPU19F2C..19FDA and19FDA..1A0F8 functions, preserving word wrap, signed ASR6 and index*6, six-byte table scan, rereads, full D0 upper-half preservation and nested helper ordering. Fixture keys came from original CPU prefix execution rather than the C formula. 32-case preflight and full1,450-case/23-guard run pass; all135 instructions covered. An initial Python conditional-expression spacing SyntaxError occurred before execution and was repaired; no restored C changes were needed. Two fresh original/C exact examples and two existing type2fixtures verify full-return/rollback edge cases.\nCodex connected these handlers to the prior CPU/GPU movement and inventory path. Original preparatory CPU+GPU state and original type2prefix determine fixture keys. Eight-case preflight then256-case linked run pass, with49type1calls/62type2calls/166redraws; all ten nested dependency targets observed. Five top-level targets and ten nested targets are still scripted; this does not establish complete lower geometry or transitions. No pinned core, native movement library or render-library changes.\n'+quality+'\nFast/initial-low exact prompts and final responses:\n'+str(Path(reasoning['first_directory'])/'prompts-and-responses.txt')+'\nLarger-low retry:\n'+str(Path(reasoning['retry_directory'])/'prompts-and-responses.txt')+'\nCoordinator reasoning audit:\n'+str(ROOT/evidence[3])+'\nReasoning capability was read from live local API; low supported. Requests changed reasoning only per call; config/default weights stayed unchanged. Live default verified off after trials. Initial low used1535reasoning tokens/nofinal; larger low used3212reasoning tokens plus123finaltokens. It still said zero instead of0x90000 for the cross64kD0 return and wrappedJSONinMarkdownfences. Fence removal was for semantic auditing, not acceptance of its strict format.\nNormal questions each retrievedboundary_handlers once, stayed under requested lengths and correctly reported0xabcd0000, neighbor95 and incomplete geometry. NativeChat stilllocked on freshUIcheck; no unlockrequest per user direction.\nPlain prompts/responses:\n'+str(path.parent/'prompts-and-responses.txt')+'\nCoordinator audit:\n'+str(ROOT/evidence[-1])+'\n'+pending+'\n')
    subprocess.run([str(ROOT/'.venv/bin/python'),str(ROOT/'scripts/install_chat_runtime.py')],check=True)
    save(ROOT/'verification/boundary-checkpoint.json',{'recorded_at':now,'backup':read(ROOT/'verification/boundary-checkpoint-backup.json')['directory'],'components':26,'CPU_components':24,'GPU_components':2,'boundary_cases':1450,'CPU_instruction_coverage':[135,135],'host_guards':23,'connected_cases':256,'connected_handler_calls':{'type1':49,'type2':62},'connected_redraws':166,'source_reasoning_scores':[3,None,6],'source_contract_fields':7,'plain_chat_questions_passed':3,'known_compute_jobs':'terminal','models':models,'reasoning_default':'off','full_goal_status':'active incomplete','evidence':evidence,'native_Chat_adoption':'unverified while locked','next_work':pending})
    print(json.dumps({'components':26,'boundary_cases':1450,'linked_cases':256,'plain_chat_questions':3,'reasoning_default':'off','installed':True}))

if __name__=='__main__':main()
